# Definition for a binary tree node.
class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def countNodes(root: TreeNode) -> int:
    # Helper to compute the left-most depth
    def leftDepth(node):
        depth = 0
        while node:
            depth += 1
            node = node.left
        return depth

    # Helper to compute the right-most depth
    def rightDepth(node):
        depth = 0
        while node:
            depth += 1
            node = node.right
        return depth

    if not root:
        return 0

    left = leftDepth(root)
    right = rightDepth(root)

    # If left and right depth are the same, it's a perfect tree
    if left == right:
        # Number of nodes in perfect binary tree = 2ⁿ - 1
        return (1 << left) - 1

    # If not perfect, count recursively for left and right subtree
    return 1 + countNodes(root.left) + countNodes(root.right)
